namespace DocSummary.Models;

public class SummaryRequest
{
    public required string DocumentText { get; set; }

    /// <summary>
    /// Maximum number of sentences to include in the summary. Defaults to 3.
    /// </summary>
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummaryResponse
{
    public required string Summary { get; set; }
    public int OriginalWordCount { get; set; }
    public int SummaryWordCount { get; set; }
}

using DocSummary.Models;

namespace DocSummary.Services;

public interface IDocumentSummarizer
{
    SummaryResponse Summarize(string documentText, int maxSentences);
}

using System.Text.RegularExpressions;
using DocSummary.Models;

namespace DocSummary.Services;

/// <summary>
/// Extractive summarizer that scores sentences by word frequency
/// and returns the top-ranked sentences in their original order.
/// </summary>
public partial class ExtractiveSummarizer : IDocumentSummarizer
{
    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
    {
        "a", "an", "the", "and", "or", "but", "is", "are", "was", "were",
        "in", "on", "at", "to", "for", "of", "with", "by", "as", "it",
        "that", "this", "from", "be", "has", "have", "had", "not", "no",
        "do", "does", "did", "will", "would", "could", "should", "may",
        "can", "if", "then", "than", "so", "its", "also", "into", "about",
        "which", "when", "where", "who", "what", "how", "been", "being",
        "each", "other", "there", "their", "they", "them", "he", "she",
        "his", "her", "we", "our", "you", "your", "i", "me", "my"
    };

    public SummaryResponse Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= maxSentences)
        {
            var fullText = string.Join(" ", sentences);
            return new SummaryResponse
            {
                Summary = fullText,
                OriginalWordCount = CountWords(documentText),
                SummaryWordCount = CountWords(fullText)
            };
        }

        var wordFrequencies = ComputeWordFrequencies(documentText);
        var scores = ScoreSentences(sentences, wordFrequencies);

        // Pick top-scoring sentence indices, then sort by original position
        var topIndices = scores
            .Select((score, index) => (score, index))
            .OrderByDescending(x => x.score)
            .Take(maxSentences)
            .Select(x => x.index)
            .Order()
            .ToList();

        var summary = string.Join(" ", topIndices.Select(i => sentences[i]));

        return new SummaryResponse
        {
            Summary = summary,
            OriginalWordCount = CountWords(documentText),
            SummaryWordCount = CountWords(summary)
        };
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return SentencePattern().Matches(text)
            .Select(m => m.Value.Trim())
            .Where(s => s.Length > 0)
            .ToList();
    }

    private static Dictionary<string, int> ComputeWordFrequencies(string text)
    {
        var frequencies = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        foreach (Match match in WordPattern().Matches(text))
        {
            var word = match.Value;
            if (word.Length > 1 && !StopWords.Contains(word))
            {
                frequencies[word] = frequencies.GetValueOrDefault(word) + 1;
            }
        }

        return frequencies;
    }

    private static List<double> ScoreSentences(
        List<string> sentences,
        Dictionary<string, int> wordFrequencies)
    {
        var scores = new List<double>(sentences.Count);

        foreach (var sentence in sentences)
        {
            var words = WordPattern().Matches(sentence);
            double score = 0;
            int wordCount = 0;

            foreach (Match match in words)
            {
                wordCount++;
                if (wordFrequencies.TryGetValue(match.Value, out int freq))
                {
                    score += freq;
                }
            }

            // Normalize by word count to avoid bias toward long sentences
            scores.Add(wordCount > 0 ? score / wordCount : 0);
        }

        return scores;
    }

    private static int CountWords(string text) =>
        WordPattern().Matches(text).Count;

    [GeneratedRegex(@"[^.!?]*[.!?]+", RegexOptions.Compiled)]
    private static partial Regex SentencePattern();

    [GeneratedRegex(@"\b\w+\b")]
    private static partial Regex WordPattern();
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly IDocumentSummarizer _summarizer;

    public SummaryController(IDocumentSummarizer summarizer)
    {
        _summarizer = summarizer;
    }

    [HttpPost]
    public IActionResult Summarize([FromBody] SummaryRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
        {
            return BadRequest(new { error = "DocumentText is required and cannot be empty." });
        }

        if (request.MaxSentences < 1)
        {
            return BadRequest(new { error = "MaxSentences must be at least 1." });
        }

        var result = _summarizer.Summarize(request.DocumentText, request.MaxSentences);
        return Ok(result);
    }
}

